"""Main Shiny application entry point."""

import json
import time
from math import ceil
from pathlib import Path
import pandas as pd
from ipyleaflet import GeoJSON, Polygon, Popup, Polyline
from ipywidgets import HTML
from shiny import App, reactive, render, ui
from shinywidgets import output_widget, render_widget

from src.mock_data import DEMO_PARKS, DEMO_ROUTES, NETWORK_STYLES
from src.data.loader import load_real_data
from src.data.map_mask import mask_feature_collection
from src.data.map_view import compute_view, expand_bounds
from src.data.network import (
    ACCESS_CLASSES,
    DEFAULT_ROAD_FILTER,
    HIGHWAY_CATEGORIES,
    feature_collection,
    load_network_data,
    make_road_filter,
    selected_lengths,
    summarise,
)
from src.ui.network_charts import network_bars, network_donuts, road_line_style
from config.paths import (
    AUCKLAND_NETWORKS_PATH,
    LOCAL_BOARDS_PATH,
    PARK_NETWORK_STATS_PATH,
    PARK_NETWORKS_PATH,
    PARK_WALKING_NETWORK_PATH,
    PARKS_PATH,
)
from src.ui.filters import filter_panel
from src.ui.results import results_panel
from src.ui.status_bar import status_bar
from src.ui.map import AUCKLAND_CENTER, PARK_SELECTION_STYLE, ROAD_PANE, create_initial_map, selected_park_layer_order
from src.ui.shell import app_ui


try:
    REAL_DATA = load_real_data(PARKS_PATH, AUCKLAND_NETWORKS_PATH, PARK_NETWORKS_PATH, LOCAL_BOARDS_PATH)
    APPLICATION_PARKS = REAL_DATA.park_records
except (FileNotFoundError, ValueError, OSError) as error:
    print(f"Real Auckland data unavailable; using demo data: {error}")
    REAL_DATA = None
    APPLICATION_PARKS = DEMO_PARKS

# Processed walking network (loaded once). None means the old path_length_km behaviour stays in effect.
NETWORK_DATA = None
if REAL_DATA is not None:
    try:
        NETWORK_DATA = load_network_data(PARK_NETWORK_STATS_PATH, PARK_WALKING_NETWORK_PATH, (park["id"] for park in APPLICATION_PARKS))
    except (FileNotFoundError, ValueError, OSError) as error:
        print(f"Processed walking network unavailable; keeping existing park lengths: {error}")

STATUS_PIN_ICON = '<svg class="status-chip-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"></path><circle cx="12" cy="10" r="3"></circle></svg>'

PARKS_BY_ID = {park["id"]: park for park in APPLICATION_PARKS}


def displayable_geometry(geometry):
    return (
        geometry is not None
        and bool(getattr(geometry, "is_empty", True)) is False
        and hasattr(geometry, "geom_type")
    )


def displayable_frame(frame):
    return frame.iloc[[index for index, geometry in enumerate(frame.geometry) if displayable_geometry(geometry)]].copy()

PARK_FOCUS_BUFFER, PARK_FOCUS_MAX_ZOOM = 0.9, 16
# Local Board / Auckland fits zoom in by this many levels (2**0.25 is about 19% closer) when the bounds still fit.
AREA_ZOOM_GAIN = 0.25
PARK_CLOSE_BUFFER, PARK_CLOSE_MAX_ZOOM = 0.2, 18

PARK_STYLE_DEFAULT = {"color": "#4F8A66", "weight": 0.6, "opacity": 0.55, "fillColor": "#78A67E", "fillOpacity": 0.45}
PARK_STYLE_OUTSIDE = {"color": "#3E6450", "weight": 0.5, "opacity": 0.45, "fillColor": "#4E7A5E", "fillOpacity": 0.5}
PARK_STYLE_INSIDE = {"color": "#6E9A7A", "weight": 0.6, "opacity": 0.5, "fillColor": "#B8D0BD", "fillOpacity": 0.85}
PARK_STYLE_MATCH = {"color": "#245B45", "weight": 0.6, "opacity": 0.55, "fillColor": "#397D5B", "fillOpacity": 0.9}
# interactive=False keeps the mask and board layers (drawn above the parks) from intercepting park clicks.
MASK_STYLE = {"stroke": False, "fillColor": "#0F1F17", "fillOpacity": 0.38, "interactive": False}
BOARD_STYLE_DEFAULT = {"color": "#7A8A7F", "weight": 1, "opacity": 1, "fillColor": "#7A8A7F", "fillOpacity": 0, "dashArray": "4", "interactive": False}
BOARD_STYLE_SELECTED = {"color": "#245B45", "weight": 1, "opacity": 0.35, "fillColor": "#245B45", "fillOpacity": 0, "dashArray": "", "interactive": False}
BOARD_STYLE_MUTED = {"color": "#C3C9C5", "weight": 1, "opacity": 1, "fillColor": "#E6E9E7", "fillOpacity": 0.05, "dashArray": "4", "interactive": False}
# Hover feedback for the invisible Local Board hit layer; kept muted so it does not compete with the cyan park selection.
BOARD_HOVER_STYLE = {"stroke": True, "color": "#245B45", "weight": 2.5, "opacity": 0.9, "fillColor": "#245B45", "fillOpacity": 0.08}


def board_hit_style(feature):
    """Invisible by default; pointer events are handled by the Local Board selection layer."""
    return {"stroke": False, "fillOpacity": 0}


def park_style_for(board: str, matching_ids=None):
    """Style by Local Board membership (local_board) and applied-filter match (GlobalID).

    matching_ids None means no filters are applied to the map: neutral styling.
    """
    def style(feature):
        properties = feature.get("properties", {})
        if board == "all" and matching_ids is None:
            return PARK_STYLE_DEFAULT
        elif board != "all" and str(properties.get("local_board") or "") != board:
            return PARK_STYLE_OUTSIDE
        elif matching_ids is not None and str(properties.get("GlobalID") or "") in matching_ids:
            return PARK_STYLE_MATCH
        return PARK_STYLE_INSIDE
    return style


def board_style_for(board: str):
    def style(feature):
        if board == "all":
            return BOARD_STYLE_DEFAULT
        name = str(feature.get("properties", {}).get("LocalBoa_2") or "")
        return BOARD_STYLE_SELECTED if name == board else BOARD_STYLE_MUTED
    return style


LOCAL_BOARD_CHOICES = {"all": "All Auckland"}
LOCAL_BOARD_CHOICES.update({
    board: board
    for board in sorted({
        park["local_board"]
        for park in APPLICATION_PARKS
        if park.get("local_board")
    })
})

# Built once at startup; selectize filters these client-side and shows at most 8 suggestions.
PARK_SEARCH_CHOICES = {
    park["id"]: f"{park['name']} · {park['local_board']}" if park.get("local_board") else park["name"]
    for park in sorted(APPLICATION_PARKS, key=lambda item: item["name"].casefold())
}


def leaflet_polygon_locations(geometry):
    if geometry is None or geometry.is_empty:
        return None
    polygons = [geometry] if geometry.geom_type == "Polygon" else list(geometry.geoms) if geometry.geom_type == "MultiPolygon" else []
    locations = []
    for polygon in polygons:
        ring = [[coordinate[1], coordinate[0]] for coordinate in polygon.exterior.coords]
        locations.append(ring)
    return locations[0] if len(locations) == 1 else locations


def leaflet_line_locations(geometry):
    if geometry is None or geometry.is_empty:
        return []
    if geometry.geom_type == "LineString":
        return [[[coordinate[1], coordinate[0]] for coordinate in geometry.coords]]
    if geometry.geom_type == "MultiLineString":
        return [[[coordinate[1], coordinate[0]] for coordinate in line.coords] for line in geometry.geoms]
    return []


def server(input, output, session):
    applied = reactive.Value({"area": "all", "speed": 4, "threshold": 10, "custom": False, "custom_speed": False})
    results_snapshot = reactive.Value([])
    has_searched = reactive.Value(False)
    view_state = reactive.Value("map")
    selected_park = reactive.Value(None)
    navigation_source = reactive.Value(None)
    filter_panel_collapsed = reactive.Value(False)
    results_panel_collapsed = reactive.Value(False)
    show_details = reactive.Value(False)
    sort_key = reactive.Value("name")
    results_scroll = reactive.Value(0)
    # Set by Local Board and cross-board park clicks; handled by switch_local_board in a reactive context.
    area_switch_request = reactive.Value(None)
    # Single source of truth for the interaction mode: False = Normal Mode, True = Select by Local Board Mode.
    board_mode = reactive.Value(False)
    # Road Filter state. The draft is the road_highway/road_access widgets (read only on Apply); road_applied is
    # written only by the shared Apply/Reset. details_road is the exploratory selection of the open Details view.
    road_applied = reactive.Value(DEFAULT_ROAD_FILTER)
    details_road = reactive.Value(DEFAULT_ROAD_FILTER)
    # Entry-specific Details input ids stop stale widget values from a previous Details view being reused.
    details_entry = reactive.Value(0)
    network_ready = NETWORK_DATA is not None

    map_widget = create_initial_map()
    map_layers = {"parks": [], "networks": {network_type: [] for network_type in NETWORK_STYLES}}
    park_tooltip_features = []
    board_tooltip_names = []

    def add_park_layers():
        for layer in map_layers["parks"]:
            map_widget.remove_layer(layer)
        map_layers["parks"] = []
        if REAL_DATA is not None:
            parks = displayable_frame(REAL_DATA.presentation_parks)
            parks["GlobalID"] = parks["GlobalID"].astype(str)
            parks.rename(columns={"DESCRIPTION": "description", "LOCALBOARD_OFFICIAL": "local_board"}, inplace=True)
            park_tooltip_features[:] = [
                {
                    "description": "" if pd.isna(row.description) else str(row.description),
                    "board": "" if pd.isna(row.local_board) else str(row.local_board),
                }
                for row in parks[["description", "local_board"]].itertuples(index=False)
            ]
            park_geojson = GeoJSON(
                data=json.loads(parks[["GlobalID", "description", "local_board", "geometry"]].to_json()),
                style={},
                style_callback=park_style_for("all"),
                hover_style={"fillOpacity": 0.45},
                name="Park boundaries",
            )

            def select_park(feature=None, **_event):
                properties = (feature or {}).get("properties", {})
                park_id = str(properties.get("GlobalID", properties.get("id", "")))
                if park_id in PARKS_BY_ID:
                    park_board = PARKS_BY_ID[park_id]["local_board"]
                    with reactive.isolate():
                        active_area = applied()["area"]
                        select_by_board = board_mode()
                    if select_by_board and park_board and park_board != active_area:
                        # Manual mode: a park in another area only switches areas (no selection, Details or zoom).
                        area_switch_request.set({"area": park_board, "nonce": time.monotonic()})
                        return
                    navigation_source.set("map")
                    results_panel_collapsed.set(False)
                    view_state.set("details")
                    open_details_filters()
                    selected_park.set(park_id)
                    show_details.set(True)
                    focus_park(park_id)

            park_geojson.on_click(select_park)
            map_layers["parks"] = [park_geojson]
            # Added by toggle_parks once the browser map view exists.
            return

        for park in APPLICATION_PARKS:
            polygon = Polygon(locations=park["bounds"], color="#4F8A66", weight=0.6, opacity=0.55, fill_color="#78A67E", fill_opacity=0.45, name=park["name"])
            def select_polygon(event, park_id=park["id"]):
                navigation_source.set("map")
                results_panel_collapsed.set(False)
                view_state.set("details")
                selected_park.set(park_id)
                show_details.set(True)
                focus_park(park_id)
            polygon.on_click(select_polygon)
            map_layers["parks"].append(polygon)
            map_widget.add(polygon)

    def add_network_layers():
        for layers in map_layers["networks"].values():
            for layer in layers:
                map_widget.remove_layer(layer)
        map_layers["networks"] = {network_type: [] for network_type in NETWORK_STYLES}
        if REAL_DATA is not None:
            return
        for park_id, routes in DEMO_ROUTES.items():
            for network_type, locations in routes:
                style = NETWORK_STYLES[network_type]
                line = Polyline(
                    locations=locations,
                    color=style["color"],
                    weight=style["weight"],
                    dash_array=style["dash"] if style["dash"] != "solid" else None,
                    name=f"{network_type}: {PARKS_BY_ID[park_id]['name']}",
                )
                map_layers["networks"][network_type].append(line)
                map_widget.add(line)

    local_board_layer = None
    if REAL_DATA is not None:
        boards = displayable_frame(REAL_DATA.local_boards)
        board_tooltip_names[:] = [
            "" if pd.isna(name) else str(name) for name in boards["LocalBoa_2"]
        ]
        local_board_layer = GeoJSON(
            data=json.loads(boards[["LocalBoa_2", "geometry"]].to_json()),
            style={},
            style_callback=board_style_for("all"),
            name="Local Board boundaries",
        )
        map_widget.add(local_board_layer)

    local_board_hit_layer = None
    if REAL_DATA is not None:
        def select_board(feature=None, **_event):
            name = str(((feature or {}).get("properties") or {}).get("LocalBoa_2") or "")
            if name:
                area_switch_request.set({"area": name, "nonce": time.monotonic()})

        # Sits in a pane below the park layer, so parks keep their own clicks, and above the non-interactive mask.
        # It is only on the map in Select by Local Board Mode (see toggle_local_boards).
        local_board_hit_layer = GeoJSON(
            data=json.loads(boards[["LocalBoa_2", "geometry"]].to_json()),
            style_callback=board_hit_style,
            hover_style=BOARD_HOVER_STYLE,
            pane="board_hit",
            options=["pm_ignore", "pane"],  # forwards the pane to the Leaflet child layers, not just the group
            name="Local Board selection",
        )
        local_board_hit_layer.on_click(select_board)

    mask_cache = {}

    def mask_data(area):
        if area not in mask_cache:
            mask_cache[area] = mask_feature_collection(REAL_DATA.local_boards, area)
        return mask_cache[area]

    mask_layer = None
    if REAL_DATA is not None:
        # Added by toggle_parks. Its own pane keeps it below the interactive board layer; it is never interactive.
        mask_layer = GeoJSON(
            data=mask_data("all"), style=dict(MASK_STYLE), name="Area mask",
            pane="area_mask", options=["pm_ignore", "pane"],
        )

    highlight_layer = GeoJSON(
        data={"type": "FeatureCollection", "features": []},
        style=dict(PARK_SELECTION_STYLE),
        name="Selected park",
    )

    add_park_layers()
    add_network_layers()

    @render_widget
    def map():
        return map_widget

    network_length_cache = {}

    def network_lengths(road):
        """Selected network length (km) per park id for a Road Filter, computed once per distinct selection."""
        if road not in network_length_cache:
            if len(network_length_cache) >= 64:
                network_length_cache.clear()
            network_length_cache[road] = selected_lengths(NETWORK_DATA.length_table, road).to_dict()
        return network_length_cache[road]

    def open_details_filters():
        """Start a Details view with the applied Road Filter; never reuses earlier temporary selections."""
        with reactive.isolate():
            details_road.set(road_applied())
            details_entry.set(details_entry() + 1)

    def calculate_matches(filters, road=None):
        """Eligible parks for the applied Park Filter and Road Filter.

        With the processed network, each park's length is its selected network length and the returned
        records carry it as "length" so Results cards, sorting and averages need no other changes.
        """
        speed = filters["speed"]
        lengths = network_lengths(road or DEFAULT_ROAD_FILTER) if network_ready else None
        threshold = filters["threshold"]
        area = filters["area"]

        def duration_at_speed(park):
            if REAL_DATA is None:
                if speed in park["duration"]:
                    return park["duration"][speed]
                base_speed = 3
                return park["duration"][base_speed] * base_speed / speed
            length = lengths.get(park["id"], 0.0) if lengths is not None else park.get("length")
            if length is None or length < 0 or speed <= 0:
                return None
            return length / speed * 60

        matches = [
            park for park in APPLICATION_PARKS
            if (area == "all" or park["local_board"] == area)
            and (duration_at_speed(park) is not None and duration_at_speed(park) > threshold)
        ]
        if lengths is None:
            return matches
        return [{**park, "length": lengths.get(park["id"], 0.0)} for park in matches]

    filter_error_text = reactive.Value("")

    @reactive.effect
    async def sync_active_board():
        area = applied()["area"]
        await session.send_custom_message("active_board", {"name": None if area == "all" else area})

    @reactive.effect
    async def sync_park_tooltip_features():
        if REAL_DATA is not None:
            await session.send_custom_message("park_tooltip_features", park_tooltip_features)
            await session.send_custom_message("board_tooltip_features", board_tooltip_names)

    @reactive.effect
    async def sync_panel_state():
        results_visible = view_state() == "details" or (has_searched() and view_state() == "results")
        await session.send_custom_message("panel_state", {
            "results_visible": results_visible,
            "results_collapsed": results_panel_collapsed(),
            "filter_collapsed": filter_panel_collapsed(),
        })

    @reactive.effect
    @reactive.event(input.toggle_filter_panel)
    def toggle_filter_panel():
        filter_panel_collapsed.set(not filter_panel_collapsed())

    @reactive.effect
    @reactive.event(input.toggle_results_panel)
    def toggle_results_panel():
        results_panel_collapsed.set(not results_panel_collapsed())

    @reactive.effect
    @reactive.event(input.apply_filters)
    def apply_filters():
        try:
            custom_speed_value = input.custom_walking_speed()
            custom_time_value = input.custom_minutes()
            custom_speed = input.walking_speed() == "custom"
            custom_time = input.walk_time() == "custom"
            if custom_speed and custom_speed_value in (None, ""):
                raise ValueError("Enter a walking speed greater than 0 km/h.")
            if custom_time and custom_time_value in (None, ""):
                raise ValueError("Enter a walking time greater than 0 minutes.")
            speed = float(custom_speed_value) if custom_speed else float(input.walking_speed())
            threshold = float(custom_time_value) if custom_time else float(input.walk_time())
            if speed <= 0 or speed > 30:
                raise ValueError("Walking speed must be between 0.1 and 30 km/h.")
            if threshold <= 0 or threshold > 180:
                raise ValueError("Walking time must be between 1 and 180 minutes.")
            next_filters = {
                "area": input.area(),
                "speed": speed,
                "threshold": ceil(threshold) if custom_time else int(threshold),
                "custom": custom_time,
                "custom_speed": custom_speed,
            }
            next_road = DEFAULT_ROAD_FILTER
            if network_ready:
                next_road = make_road_filter(input.road_highway() or (), input.road_access() or ())
                if not next_road.categories:
                    raise ValueError("Select at least one highway category.")
                if not next_road.access:
                    raise ValueError("Select at least one pedestrian accessibility class.")
            filter_error_text.set("")
        except (TypeError, ValueError) as error:
            filter_error_text.set(str(error))
            return

        # Both filter groups validated: commit them together.
        applied.set(next_filters)
        road_applied.set(next_road)
        next_matches = calculate_matches(next_filters, next_road)
        results_snapshot.set(next_matches)
        refresh_applied_map_styles(next_filters, next_matches)
        has_searched.set(True)
        view_state.set("results")
        results_panel_collapsed.set(False)
        show_details.set(False)
        selected_park.set(None)
        fit_after_layout(next_filters)

    @reactive.effect
    @reactive.event(input.reset_filters)
    def reset_filters():
        ui.update_select("area", selected="all")
        ui.update_radio_buttons("walking_speed", selected="4")
        ui.update_radio_buttons("walk_time", selected="10")
        ui.update_numeric("custom_walking_speed", value="")
        ui.update_numeric("custom_minutes", value="")
        filter_error_text.set("")
        reset_filters_state = {
            "area": "all",
            "speed": 4,
            "threshold": 10,
            "custom": False,
            "custom_speed": False,
        }
        applied.set(reset_filters_state)
        road_applied.set(DEFAULT_ROAD_FILTER)
        if network_ready:
            ui.update_checkbox_group("road_highway", selected=list(HIGHWAY_CATEGORIES))
            ui.update_checkbox_group("road_access", selected=["Walkable"])
        results_snapshot.set(calculate_matches(reset_filters_state, DEFAULT_ROAD_FILTER))
        has_searched.set(True)
        refresh_applied_map_styles(reset_filters_state, None)
        view_state.set("results")
        results_panel_collapsed.set(False)
        show_details.set(False)
        selected_park.set(None)
        fit_after_layout(reset_filters_state)

    @reactive.effect
    @reactive.event(area_switch_request)
    def switch_local_board():
        request = area_switch_request()
        board = request["area"]
        current = applied()
        if board == current["area"]:
            return
        # Only the area changes: applied speed/time are reused, and unsaved draft inputs stay unapplied.
        next_filters = {**current, "area": board}
        ui.update_select("area", selected=board)
        applied.set(next_filters)
        selected_park.set(None)
        show_details.set(False)
        if not has_searched():
            # No filters applied yet: change the area, mask and zoom only, without creating a Results snapshot.
            refresh_applied_map_styles(next_filters, None)
            view_state.set("map")
            fit_after_layout(next_filters)
            return
        next_matches = calculate_matches(next_filters, road_applied())
        results_snapshot.set(next_matches)
        refresh_applied_map_styles(next_filters, next_matches)
        view_state.set("results")
        results_panel_collapsed.set(False)
        fit_after_layout(next_filters)

    @render.ui
    def filter_error():
        if filter_error_text():
            return ui.tags.div(filter_error_text(), class_="filter-error", role="alert")
        return ui.tags.div()

    def keep_selected_demo_park_above_parks(park_id, selected_layer=None):
        if REAL_DATA is not None or not park_id:
            return
        if selected_layer is None:
            park_name = PARKS_BY_ID.get(park_id, {}).get("name")
            selected_layer = next(
                (layer for layer in map_layers["parks"] if layer.name == park_name),
                None,
            )
        if selected_layer is None:
            return
        ordered_layers = selected_park_layer_order(
            map_widget.layers,
            map_layers["parks"],
            selected_layer,
        )
        if any(before is not after for before, after in zip(map_widget.layers, ordered_layers)):
            map_widget.layers = ordered_layers

    @reactive.effect
    def toggle_parks():
        input.map_viewport()  # first value arrives after the browser map view has been created
        if mask_layer is not None and mask_layer not in map_widget.layers:
            map_widget.add(mask_layer)
        for layer in map_layers["parks"]:
            if isinstance(layer, GeoJSON):
                if not hasattr(layer, "_greenspace_all_data"):
                    setattr(layer, "_greenspace_all_data", layer.data)
                should_show = input.show_parks()
            else:
                should_show = input.show_parks()
            if should_show and layer not in map_widget.layers:
                map_widget.add(layer)
            elif not should_show and layer in map_widget.layers:
                map_widget.remove_layer(layer)
        if REAL_DATA is None:
            with reactive.isolate():
                keep_selected_demo_park_above_parks(selected_park())

    @reactive.effect
    @reactive.event(input.toggle_board_mode)
    async def toggle_board_mode():
        board_mode.set(not board_mode())
        await session.send_custom_message("board_mode", {"active": board_mode()})

    @reactive.effect
    def toggle_local_boards():
        should_show = bool(input.show_local_boards()) and local_board_layer is not None
        if should_show and local_board_layer not in map_widget.layers:
            map_widget.add(local_board_layer)
        elif local_board_layer is not None and not should_show and local_board_layer in map_widget.layers:
            map_widget.remove_layer(local_board_layer)
        if local_board_hit_layer is not None:
            # The interactive board layer exists only in Select by Local Board Mode, so it cannot touch Normal Mode clicks.
            show_hit = should_show and board_mode()
            if show_hit and local_board_hit_layer not in map_widget.layers:
                map_widget.add(local_board_hit_layer)
            elif not show_hit and local_board_hit_layer in map_widget.layers:
                map_widget.remove_layer(local_board_hit_layer)

    @reactive.effect
    @reactive.event(input.show_networks)
    def toggle_networks():
        for layers in map_layers["networks"].values():
            for layer in layers:
                if input.show_networks() and layer not in map_widget.layers:
                    map_widget.add(layer)
                elif not input.show_networks() and layer in map_widget.layers:
                    map_widget.remove_layer(layer)

    @reactive.effect
    def toggle_network_types():
        visibility = {
            "Footway": input.show_footway(),
            "Path": input.show_path(),
            "Track": input.show_track(),
            "Steps": input.show_steps(),
        }
        for network_type, layers in map_layers["networks"].items():
            for layer in layers:
                should_show = input.show_networks() and visibility[network_type]
                if should_show and layer not in map_widget.layers:
                    map_widget.add(layer)
                elif not should_show and layer in map_widget.layers:
                    map_widget.remove_layer(layer)

    @reactive.effect
    @reactive.event(input.selected_result_park)
    def select_result_park():
        park_id = input.selected_result_park()
        if park_id in PARKS_BY_ID:
            navigation_source.set("results")
            view_state.set("details")
            open_details_filters()
            selected_park.set(park_id)
            show_details.set(True)
            focus_park(park_id)

    @reactive.effect
    @reactive.event(input.park_search, ignore_none=True, ignore_init=True)
    def select_searched_park():
        park_id = input.park_search()
        # An empty value is the search being cleared: leave selection, Details and filters untouched.
        if park_id not in PARKS_BY_ID:
            return
        # Same navigation path as a map click, without touching the applied filters or Results snapshot.
        navigation_source.set("map")
        results_panel_collapsed.set(False)
        view_state.set("details")
        open_details_filters()
        selected_park.set(park_id)
        show_details.set(True)
        focus_park(park_id)
        # Reset the box so the same park can be searched again later.
        ui.update_selectize("park_search", selected="")

    def padded_bounds(bounds):
        min_latitude, min_longitude, max_latitude, max_longitude = bounds
        latitude_padding = max((max_latitude - min_latitude) * 0.12, 0.008)
        longitude_padding = max((max_longitude - min_longitude) * 0.12, 0.008)
        return (
            min_latitude - latitude_padding,
            min_longitude - longitude_padding,
            max_latitude + latitude_padding,
            max_longitude + longitude_padding,
        )

    def area_bounds(area):
        """(south, west, north, east) of the selected Local Board boundary, or of all boards."""
        if REAL_DATA is None:
            return None
        boards = REAL_DATA.local_boards
        if area != "all":
            boards = boards[boards["LocalBoa_2"].astype(str) == area]
        if boards.empty:
            return None
        min_x, min_y, max_x, max_y = boards.total_bounds
        return (min_y, min_x, max_y, max_x)

    def current_viewport():
        with reactive.isolate():
            try:
                return input.map_viewport()
            except Exception as error:
                print(f"map viewport unavailable: {error!r}")
                return None

    def fit_applied_area(filters):
        if REAL_DATA is None:
            map_widget.center = AUCKLAND_CENTER
            map_widget.zoom = 12
            return
        bounds = area_bounds(filters["area"])
        if bounds is None:
            return
        viewport = current_viewport()
        if viewport is None:
            south, west, north, east = padded_bounds(bounds)
            map_widget.fit_bounds([[south, west], [north, east]])
            return
        center, zoom = compute_view(bounds, viewport, gain=AREA_ZOOM_GAIN)
        map_widget.center = center
        map_widget.zoom = zoom

    pending_fit = {"filters": None, "until": 0.0}

    def fit_after_layout(filters):
        # The Results panel opens after Apply and resizes the map, so keep refitting to the
        # applied area for a short window as the browser reports the new map size.
        fit_applied_area(filters)
        pending_fit["filters"] = filters
        pending_fit["until"] = time.monotonic() + 1.5

    initial_fit_done = {"value": False}

    @reactive.effect
    def fit_on_viewport_change():
        input.map_viewport()
        if not initial_fit_done["value"]:
            initial_fit_done["value"] = True
            with reactive.isolate():
                fit_applied_area(applied())
        elif pending_fit["filters"] is not None and time.monotonic() < pending_fit["until"]:
            fit_applied_area(pending_fit["filters"])

    styled_state = {"key": ("all", None)}

    def refresh_applied_map_styles(filters, matches):
        selected_board = filters["area"]
        matching_ids = None if matches is None else frozenset(park["id"] for park in matches)
        key = (selected_board, matching_ids)
        if styled_state["key"] == key:
            return
        styled_state["key"] = key
        # Restyling re-creates a layer's paths in the browser, so restyle bottom-up: mask, parks, then boards.
        if mask_layer is not None:
            data = mask_data(selected_board)
            if mask_layer.data is not data:
                mask_layer.data = data
        for layer in map_layers["parks"]:
            if isinstance(layer, GeoJSON):
                layer.style_callback = park_style_for(selected_board, matching_ids)
        if local_board_layer is not None:
            local_board_layer.style_callback = board_style_for(selected_board)

    def park_bounds(park_id):
        coordinates = PARKS_BY_ID[park_id]["bounds"]
        latitudes = [coordinate[0] for coordinate in coordinates]
        longitudes = [coordinate[1] for coordinate in coordinates]
        return (min(latitudes), min(longitudes), max(latitudes), max(longitudes))

    def focus_park(park_id, closer=False):
        """Shared park zoom for map clicks, Results cards and "Zoom to park".

        The park bounds are expanded by a buffer so streets around the park stay visible, then
        fitted inside the unobstructed map area. The buffer scales with park size, and a maximum
        zoom stops small parks becoming extreme close-ups. closer=True uses a smaller buffer and
        a higher zoom cap, so it is never further out than the initial view.
        """
        if park_id not in PARKS_BY_ID:
            return
        buffer, max_zoom = (PARK_CLOSE_BUFFER, PARK_CLOSE_MAX_ZOOM) if closer else (PARK_FOCUS_BUFFER, PARK_FOCUS_MAX_ZOOM)
        bounds = expand_bounds(park_bounds(park_id), buffer)
        viewport = current_viewport()
        if viewport is None:
            map_widget.fit_bounds([[bounds[0], bounds[1]], [bounds[2], bounds[3]]])
            return
        center, zoom = compute_view(bounds, viewport, max_zoom=max_zoom)
        # Setting centre and zoom makes the browser animate the view change.
        map_widget.center = center
        map_widget.zoom = zoom

    def fit_selected_park():
        focus_park(selected_park(), closer=True)

    @reactive.effect
    def highlight_selected():
        park_id = selected_park()
        if REAL_DATA is None:
            selected_layer = None
            for layer in map_layers["parks"]:
                if layer.name == PARKS_BY_ID.get(park_id, {}).get("name"):
                    selected_layer = layer
                    layer.color = PARK_SELECTION_STYLE["color"]
                    layer.weight = PARK_SELECTION_STYLE["weight"]
                    layer.opacity = 1
                    layer.fill_color = PARK_SELECTION_STYLE["fillColor"]
                    layer.fill_opacity = PARK_SELECTION_STYLE["fillOpacity"]
                else:
                    layer.color = "#4F8A66"
                    layer.weight = 0.6
                    layer.opacity = 0.55
                    layer.fill_color = "#78A67E"
                    layer.fill_opacity = 0.45
            keep_selected_demo_park_above_parks(park_id, selected_layer)
            return
        feature = None
        if park_id and REAL_DATA is not None:
            for park in getattr(map_layers["parks"][0], "_greenspace_all_data", {}).get("features", []):
                if str(park["properties"].get("GlobalID", "")) == str(park_id):
                    feature = park
                    break
        highlight_data = {"type": "FeatureCollection", "features": [feature] if feature else []}
        if highlight_layer.data != highlight_data:
            highlight_layer.data = highlight_data
        if feature and highlight_layer not in map_widget.layers:
            map_widget.add(highlight_layer)
        elif not feature and highlight_layer in map_widget.layers:
            map_widget.remove_layer(highlight_layer)

    EMPTY_COLLECTION = {"type": "FeatureCollection", "features": []}
    road_layer = None
    if network_ready:
        # One line layer in its own non-interactive pane; only the scoped, filtered roads are ever sent to the browser.
        road_layer = GeoJSON(
            data=EMPTY_COLLECTION, style={"interactive": False}, name="Walking network",
            pane=ROAD_PANE, options=["pm_ignore", "pane"],
        )
    road_state = {"key": None}
    road_cache = {}

    def road_scope():
        """(park ids, RoadFilter) whose roads should be drawn, or None.

        Details: the selected park with the temporary Details selection. Road Filter tab with a Local Board
        selected: the Results parks with the applied Road Filter. All Auckland draws nothing (rendering limit only).
        """
        if not network_ready or not input.show_networks():
            return None
        if show_details() and selected_park() in PARKS_BY_ID:
            return (selected_park(),), details_road()
        if input.filter_tab() == "Road Filter" and has_searched() and applied()["area"] != "all":
            return tuple(park["id"] for park in results_snapshot()), road_applied()
        return None

    @reactive.effect
    def sync_road_layer():
        input.map_viewport()  # layers are added only after the browser map view exists
        if road_layer is None:
            return
        scope = road_scope()
        key = (scope[0], scope[1]) if scope is not None and scope[1].is_valid else None
        if key != road_state["key"]:
            road_state["key"] = key
            if key is None:
                collection = EMPTY_COLLECTION
            else:
                if key not in road_cache:
                    if len(road_cache) >= 16:
                        road_cache.clear()
                    road_cache[key] = feature_collection(NETWORK_DATA.features_by_park, key[0], key[1], road_line_style)
                collection = road_cache[key]
            road_layer.data = collection
        has_roads = key is not None and bool(road_layer.data["features"])
        if has_roads and road_layer not in map_widget.layers:
            map_widget.add(road_layer)
        elif not has_roads and road_layer in map_widget.layers:
            map_widget.remove_layer(road_layer)

    @reactive.effect
    def sync_details_road():
        # Only the current entry's widgets are read; their values never reach the main draft or applied state.
        entry = details_entry()
        categories = input[f"detail_highway_{entry}"]()
        access = input[f"detail_access_{entry}"]()
