"""Load and adapt the Auckland Greenspace GIS datasets."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import geopandas as gpd
import pandas as pd
from shapely.geometry import MultiPolygon

PROCESSING_CRS = "EPSG:2193"
DISPLAY_CRS = "EPSG:4326"
SIMPLIFY_CRS = "EPSG:2193"
PRESENTATION_SIMPLIFY_TOLERANCE_M = 1.0

NETWORK_CATEGORY_MAPPING = {
    "footway": "Footway",
    "path": "Path",
    "track": "Track",
    "steps": "Steps",
    "service": "Service road",
    "cycleway": "Cycleway",
    "residential": "Road",
    "primary": "Road",
    "secondary": "Road",
    "tertiary": "Road",
    "living_street": "Road",
    "pedestrian": "Pedestrian",
    "bridleway": "Bridleway",
    "unclassified": "Unclassified",
}


def _network_composition(network: gpd.GeoDataFrame, park_id: str) -> dict[str, float]:
    park_network = network[(network["GlobalID"].notna()) & (network["GlobalID"].astype(str) == park_id)].copy()
    if park_network.empty:
        return {}

    categories: dict[str, float] = {}
    for _, segment in park_network.iterrows():
        highway = str(segment["highway"]).strip().lower() if pd.notna(segment["highway"] ) else "unclassified"
        category = NETWORK_CATEGORY_MAPPING.get(highway, "Other")
        length = pd.to_numeric(pd.Series([segment.get("length_km")]), errors="coerce").iloc[0]
        if pd.isna(length) or length < 0:
            continue
        categories[category] = categories.get(category, 0.0) + float(length)

    total = sum(categories.values())
    if total <= 0:
        return {}
    return {
        category: round(length / total * 100, 1)
        for category, length in sorted(categories.items(), key=lambda item: item[1], reverse=True)
        if length > 0
    }


@dataclass(frozen=True)
class RealData:
    parks: gpd.GeoDataFrame
    presentation_parks: gpd.GeoDataFrame
    park_records: list[dict[str, Any]]
    park_network: gpd.GeoDataFrame
    local_boards: gpd.GeoDataFrame
    auckland_network_loaded: bool
    spatial_network_match_summary: dict[str, int | float]


def _require_columns(frame: gpd.GeoDataFrame, columns: set[str], source: Path) -> None:
    missing = sorted(columns.difference(frame.columns))
    if missing:
        raise ValueError(f"{source} is missing required fields: {', '.join(missing)}")


def _to_processing_crs(frame: gpd.GeoDataFrame, source: Path) -> gpd.GeoDataFrame:
    if frame.crs is None:
        raise ValueError(f"{source} is missing a coordinate reference system")
    if frame.crs.to_epsg() != 2193:
        frame = frame.to_crs(PROCESSING_CRS)
    return frame


def displayable_geometry(geometry: Any) -> bool:
    return (
        geometry is not None
        and hasattr(geometry, "is_empty")
        and not geometry.is_empty
        and hasattr(geometry, "geom_type")
    )


def _displayable_indices(frame: gpd.GeoDataFrame) -> list[int]:
    return [
        index
        for index, geometry in enumerate(frame.geometry)
        if geometry is not None
        and hasattr(geometry, "is_empty")
        and not geometry.is_empty
        and hasattr(geometry, "geom_type")
    ]


def _presentation_parks_geometries(
    frame: gpd.GeoDataFrame, tolerance_metres: float = PRESENTATION_SIMPLIFY_TOLERANCE_M
) -> gpd.GeoDataFrame:
    frame = frame.iloc[_displayable_indices(frame)].copy()
    valid = frame.geometry.apply(lambda geometry: geometry.is_valid)
    invalid = ~valid
    if invalid.any():
        frame.loc[invalid, "geometry"] = frame.loc[invalid, "geometry"].apply(
            lambda geometry: geometry.make_valid()
        )
    # Display copy only: simplify in metres (EPSG:2193), then reproject for the web map.
    frame = frame.to_crs(SIMPLIFY_CRS)
    frame["geometry"] = frame.geometry.simplify(tolerance_metres, preserve_topology=True)
    return frame.to_crs(DISPLAY_CRS)


def _presentation_geometries(frame: gpd.GeoDataFrame) -> gpd.GeoDataFrame:
    frame = frame.copy()
    displayable = frame.geometry.apply(lambda geometry: displayable_geometry(geometry))
    valid = displayable & frame.geometry.apply(
        lambda geometry: geometry.is_valid if displayable_geometry(geometry) else False
    )
    invalid = displayable & ~valid
    if invalid.any():
        frame.loc[invalid, "geometry"] = frame.loc[invalid, "geometry"].apply(
            lambda geometry: geometry.make_valid()
        )
    return frame.to_crs(DISPLAY_CRS)


def _bounds_for_geometry(geometry: Any) -> list[list[float]] | None:
    if geometry is None or geometry.is_empty:
        return None
    geometry = geometry if geometry.is_valid else geometry.make_valid()
    min_x, min_y, max_x, max_y = geometry.bounds
    return [[min_y, min_x], [max_y, max_x]]


def load_real_data(
    parks_path: Path,
    auckland_network_path: Path,
    park_network_path: Path,
    local_boards_path: Path,
) -> RealData:
    parks = gpd.read_file(parks_path, layer="parks")
    park_network = gpd.read_file(park_network_path)
    local_boards = gpd.read_file(local_boards_path)

    _require_columns(parks, {"GlobalID", "DESCRIPTION", "LOCALBOARD_OFFICIAL", "area_km2", "path_length_km"}, parks_path)
    _require_columns(park_network, {"highway"}, park_network_path)
    _require_columns(local_boards, {"LocalBoa_2"}, local_boards_path)

    parks = _to_processing_crs(parks, parks_path)
    park_network = _to_processing_crs(park_network, park_network_path)
    local_boards = _to_processing_crs(local_boards, local_boards_path)

    global_ids = parks["GlobalID"].dropna().astype(str)
    if global_ids.duplicated().any():
        duplicates = sorted(global_ids[global_ids.duplicated()].unique().tolist())
        raise ValueError(f"Duplicate park GlobalIDs found: {', '.join(duplicates[:10])}")

    null_global_ids = parks["GlobalID"].isna().sum()
    if null_global_ids:
        raise ValueError(f"{null_global_ids} parks are missing GlobalID")

    records: list[dict[str, Any]] = []
    for _, park in parks.iterrows():
        geometry = park.geometry
        bounds = None
        if geometry is not None and not geometry.is_empty:
            try:
                bounds = _bounds_for_geometry(geometry)
            except (AttributeError, ValueError, TypeError):
                bounds = None
        if geometry is not None and not geometry.is_empty and geometry.is_valid:
            bounds_geometry = geometry
        elif geometry is not None and not geometry.is_empty:
            try:
                bounds_geometry = geometry.make_valid()
            except (AttributeError, ValueError, TypeError):
                bounds_geometry = None
        else:
            bounds_geometry = None
        raw_length = park["path_length_km"]
        length = pd.to_numeric(pd.Series([raw_length]), errors="coerce").iloc[0]
        length = float(length) if pd.notna(length) and length >= 0 else None
        area = pd.to_numeric(pd.Series([park["area_km2"]]), errors="coerce").iloc[0]
        area_hectares = float(area * 100) if pd.notna(area) else None
        records.append({
            "id": str(park["GlobalID"]),
            "name": str(park["DESCRIPTION"]) if pd.notna(park["DESCRIPTION"]) else "Unnamed park",
            "local_board": str(park["LOCALBOARD_OFFICIAL"]) if pd.notna(park["LOCALBOARD_OFFICIAL"]) else "",
            "area": area_hectares,
            "length": length,
            "bounds": bounds,
            "geometry": geometry,
            "network": _network_composition(park_network, str(park["GlobalID"])),
            "duration": {},
        })

    presentation_parks = _presentation_parks_geometries(parks)
    presentation_parks_full = _presentation_geometries(parks)
    bounds_by_global_id = {
        str(park_id): _bounds_for_geometry(geometry)
        for park_id, geometry in presentation_parks_full.set_index("GlobalID").geometry.items()
    }
    for record in records:
        if record["id"] in bounds_by_global_id:
            record["bounds"] = bounds_by_global_id[record["id"]]

    presentation_network = _presentation_geometries(park_network)
    presentation_boards = _presentation_geometries(local_boards)

    # Spatial matching is diagnostic only: no network segment is assigned to a
    # park until a reliable source-level association exists.
    spatial_matches = 0
    ambiguous_matches = 0
    if "SAPID" in park_network.columns:
        linked_records = park_network[park_network["SAPID"].notna() & park_network["SAPID"].isin(parks["SAPID"])].shape[0]
        duplicate_sapids = parks["SAPID"].dropna().duplicated(keep=False).sum() if "SAPID" in parks.columns else 0
        spatial_matches = int(linked_records)
        ambiguous_matches = int(duplicate_sapids)

    # Explicitly avoid loading Auckland-wide lines into browser memory.
    # The file remains available for future viewport/server-side loading.
    auckland_network_loaded = False
    if auckland_network_path.exists():
        with auckland_network_path.open("rb"):
            pass

    presentation_parks = presentation_parks.set_crs(DISPLAY_CRS, allow_override=True)
    presentation_network = presentation_network.set_crs(DISPLAY_CRS, allow_override=True)
    presentation_boards = presentation_boards.set_crs(DISPLAY_CRS, allow_override=True)

    return RealData(
        parks=presentation_parks_full,
        presentation_parks=presentation_parks,
        park_records=records,
        park_network=presentation_network,
        local_boards=presentation_boards,
        auckland_network_loaded=auckland_network_loaded,
        spatial_network_match_summary={
            "source_associated_segments": spatial_matches,
            "duplicate_sapid_rows": ambiguous_matches,
        },
    )

"""Processed park walking network: lengths, eligibility, statistics and road features.

Lengths are geometry lengths in EPSG:2193 (km), precomputed by
scripts/preprocess_park_walking_network.py. Classification (highway_category,
pedestrian_access) is read as stored and is never recomputed here.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path
import sys
from typing import Any

import geopandas as gpd
import pandas as pd
import shapely
from shapely.geometry import mapping

HIGHWAY_CATEGORIES: tuple[str, ...] = (
    "Walking paths", "Nature trails", "Shared-use paths", "Local roads", "Major roads",
)
ACCESS_CLASSES: tuple[str, ...] = ("Walkable", "Conditional", "Restricted")
SOURCE_CRS_EPSG = 2193
DISPLAY_CRS = "EPSG:4326"
COORDINATE_PRECISION = 1e-6
PARK_ID_FIELD = "GlobalID"

STATS_COLUMNS = {"park_id", "highway_category", "pedestrian_access", "feature_count", "length_km"}
FEATURE_COLUMNS = [PARK_ID_FIELD, "highway_category", "pedestrian_access", "length_km"]
COLUMN_PAIRS = pd.MultiIndex.from_product([HIGHWAY_CATEGORIES, ACCESS_CLASSES], names=["highway_category", "pedestrian_access"])


@dataclass(frozen=True)
class RoadFilter:
    """An applied or draft Road Filter selection (immutable, so it is safe to share between states)."""

    categories: frozenset[str]
    access: frozenset[str]

    @property
    def is_valid(self) -> bool:
        return bool(self.categories) and bool(self.access)

    @property
    def columns(self) -> list[tuple[str, str]]:
        return [
            (category, access)
            for category in HIGHWAY_CATEGORIES if category in self.categories
            for access in ACCESS_CLASSES if access in self.access
        ]


def make_road_filter(categories: Iterable[str], access: Iterable[str]) -> RoadFilter:
    categories, access = frozenset(categories), frozenset(access)
    unknown = (categories - set(HIGHWAY_CATEGORIES)) | (access - set(ACCESS_CLASSES))
    if unknown:
        raise ValueError(f"Unknown road filter values: {', '.join(sorted(unknown))}")
    return RoadFilter(categories, access)


DEFAULT_ROAD_FILTER = RoadFilter(frozenset(HIGHWAY_CATEGORIES), frozenset({"Walkable"}))


def load_network_stats(path: Path) -> pd.DataFrame:
    """Read the pre-aggregated Parquet statistics and validate its schema and vocabulary."""
    stats = pd.read_parquet(path)
    missing = STATS_COLUMNS - set(stats.columns)
    if missing:
        raise ValueError(f"{path} is missing columns: {', '.join(sorted(missing))}")
    if stats[["park_id", "highway_category", "pedestrian_access", "length_km"]].isna().any().any():
        raise ValueError(f"{path} contains null keys or lengths")
    if (stats["length_km"] < 0).any():
        raise ValueError(f"{path} contains negative lengths")
    for column, vocabulary in (("highway_category", HIGHWAY_CATEGORIES), ("pedestrian_access", ACCESS_CLASSES)):
        unknown = set(stats[column]) - set(vocabulary)
        if unknown:
            raise ValueError(f"{path} has unexpected {column} values: {', '.join(sorted(map(str, unknown)))}")
    if stats.duplicated(["park_id", "highway_category", "pedestrian_access"]).any():
        raise ValueError(f"{path} has duplicate park/category/access rows")
    return stats


def build_length_table(stats: pd.DataFrame, park_ids: Iterable[str]) -> pd.DataFrame:
    """Dense km table: one row per park, one column per (highway_category, pedestrian_access).

    Parks with no network rows get zeros. Statistics for unknown parks are an error, not silently dropped.
    """
    park_ids = pd.Index([str(park_id) for park_id in park_ids], name="park_id")
    unknown = set(stats["park_id"].astype(str)) - set(park_ids)
    if unknown:
        raise ValueError(f"{len(unknown)} statistics park_ids are not in the park dataset, e.g. {sorted(unknown)[:3]}")
    table = (
        stats.assign(park_id=stats["park_id"].astype(str))
        .pivot_table(index="park_id", columns=["highway_category", "pedestrian_access"], values="length_km", aggfunc="sum")
        .reindex(index=park_ids, columns=COLUMN_PAIRS)
        .fillna(0.0)
    )
    return table


def selected_lengths(table: pd.DataFrame, road: RoadFilter) -> pd.Series:
    """Selected network length (km) per park for a Road Filter selection."""
    columns = road.columns
    if not columns:
        return pd.Series(0.0, index=table.index)
    return table.loc[:, columns].sum(axis=1)


def walking_minutes(length_km: float | pd.Series, speed_kmh: float) -> float | pd.Series:
    return length_km / speed_kmh * 60


def eligible_park_ids(lengths: pd.Series, speed_kmh: float, threshold_minutes: float) -> set[str]:
    """Parks whose walking time is strictly greater than the minimum walking time."""
    if speed_kmh <= 0:
        return set()
    return set(lengths.index[walking_minutes(lengths, speed_kmh) > threshold_minutes])


def matching_park_ids(
    parks: Iterable[Mapping[str, Any]],
    lengths: pd.Series,
    area: str,
    speed_kmh: float,
    threshold_minutes: float,
) -> list[str]:
    """Park ids inside the area ("all" or a Local Board name) with walking time strictly above the threshold.

    Mirrors the application's scope rule: area == "all" or park["local_board"] == area.
    """
    if speed_kmh <= 0:
        return []
    return [
        park["id"] for park in parks
        if (area == "all" or park["local_board"] == area)
        and park["id"] in lengths.index
        and lengths[park["id"]] / speed_kmh * 60 > threshold_minutes
    ]


@dataclass(frozen=True)
class NetworkData:
    """Processed walking-network data, loaded once at startup and shared read-only."""

    length_table: pd.DataFrame
    features_by_park: dict[str, tuple[dict[str, Any], ...]]


def load_network_data(stats_path: Path, features_path: Path, park_ids: Iterable[str]) -> NetworkData:
    """Load and cross-validate both processed datasets against the application's park ids.

    Raises FileNotFoundError, OSError or ValueError so the caller can fall back gracefully.
    """
    park_ids = [str(park_id) for park_id in park_ids]
    for path in (stats_path, features_path):
        if not Path(path).exists():
            raise FileNotFoundError(f"Processed network file not found: {path}")
    stats = load_network_stats(stats_path)
    table = build_length_table(stats, park_ids)
    features = load_network_features(features_path)
    unknown = set(features) - set(park_ids)
    if unknown:
        raise ValueError(f"{len(unknown)} network features reference unknown park ids, e.g. {sorted(unknown)[:3]}")
    if set(features) != set(stats["park_id"].astype(str)):
        raise ValueError("GeoPackage and Parquet cover different parks")
    feature_total = sum(len(group) for group in features.values())
    if feature_total != int(stats["feature_count"].sum()):
        raise ValueError(f"Feature count mismatch: GeoPackage {feature_total} vs Parquet {int(stats['feature_count'].sum())}")
    return NetworkData(table, features)


@dataclass(frozen=True)
class NetworkSummary:
    total_km: float
    by_access: dict[str, float]
    by_category: dict[str, float]


def summarise(table: pd.DataFrame, park_ids: Iterable[str], road: RoadFilter) -> NetworkSummary:
    """Both chart breakdowns come from one filtered slice, so they share the same total."""
    ids = [park_id for park_id in dict.fromkeys(map(str, park_ids)) if park_id in table.index]
    columns = road.columns
    by_access = dict.fromkeys(ACCESS_CLASSES, 0.0)
    by_category = dict.fromkeys(HIGHWAY_CATEGORIES, 0.0)
    if ids and columns:
        totals = table.loc[ids, columns].sum()
        for (category, access), value in totals.items():
            by_access[access] += float(value)
            by_category[category] += float(value)
    return NetworkSummary(sum(by_access.values()), by_access, by_category)


def shares(values: Mapping[str, float], total: float) -> dict[str, float]:
    """Percentages of a shared denominator; empty when there is nothing to show."""
    if total <= 0:
        return {}
    return {key: value / total * 100 for key, value in values.items()}


def load_network_features(path: Path, layer: str = "park_walking_network") -> dict[str, tuple[dict[str, Any], ...]]:
    """Read the processed GeoPackage once; return GeoJSON-like features grouped by park id (EPSG:4326)."""
    engine = "fiona" if sys.platform == "emscripten" else "pyogrio"
    frame = gpd.read_file(path, layer=layer, columns=FEATURE_COLUMNS, engine=engine)
    if frame.crs is None or frame.crs.to_epsg() != SOURCE_CRS_EPSG:
        raise ValueError(f"{path} layer {layer} must be EPSG:{SOURCE_CRS_EPSG}, found {frame.crs}")
    if frame[PARK_ID_FIELD].isna().any():
        raise ValueError(f"{path} has road features without {PARK_ID_FIELD}")
    for column, vocabulary in (("highway_category", HIGHWAY_CATEGORIES), ("pedestrian_access", ACCESS_CLASSES)):
        unknown = set(frame[column].dropna()) - set(vocabulary)
        if frame[column].isna().any() or unknown:
            raise ValueError(f"{path} has missing or unexpected {column} values")
    frame = frame.to_crs(DISPLAY_CRS)
    geometries = shapely.set_precision(frame.geometry.to_numpy(), COORDINATE_PRECISION)
    grouped: dict[str, list[dict[str, Any]]] = {}
    for park_id, category, access, geometry in zip(
        frame[PARK_ID_FIELD].astype(str), frame["highway_category"], frame["pedestrian_access"], geometries
    ):
        grouped.setdefault(park_id, []).append({
            "type": "Feature",
            "properties": {"GlobalID": park_id, "highway_category": category, "pedestrian_access": access},
            "geometry": mapping(geometry),
        })
    return {park_id: tuple(features) for park_id, features in grouped.items()}


def feature_collection(
    features_by_park: Mapping[str, Sequence[dict[str, Any]]],
    park_ids: Iterable[str],
    road: RoadFilter,
    style_for: Callable[[str, str], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """GeoJSON FeatureCollection of the selected roads for the given parks only.

    A per-feature style is embedded in properties.style so ipyleaflet does not need a Python style callback.
    """
    features = []
    for park_id in dict.fromkeys(map(str, park_ids)):
        for feature in features_by_park.get(park_id, ()):
            properties = feature["properties"]
            category, access = properties["highway_category"], properties["pedestrian_access"]
            if category not in road.categories or access not in road.access:
                continue
            if style_for is None:
                features.append(feature)
            else:
                features.append({**feature, "properties": {**properties, "style": style_for(category, access)}})
    return {"type": "FeatureCollection", "features": features}

"""Rendering helpers for the walking-network charts and road line styles (no business rules).

Visual encoding: colour always means highway category (donut, legend, map lines);
pedestrian accessibility uses neutral greys with solid/striped/dotted textures instead.
"""

from __future__ import annotations

from collections.abc import Mapping

from shiny import ui

from src.data.network import ACCESS_CLASSES, HIGHWAY_CATEGORIES, NetworkSummary, shares

# One palette for map road lines, the donut and the legends.
CATEGORY_COLORS = {
    "Walking paths": "#287A55",
    "Nature trails": "#D99A27",
    "Shared-use paths": "#258A9B",
    "Local roads": "#6476A5",
    "Major roads": "#C65D4B",
}
# Neutral textures: solid, dash-dot, dots. Deliberately not part of the highway palette.
ACCESS_FILLS = {
    "Walkable": "#4B5563",
    "Conditional": "repeating-linear-gradient(90deg, #4B5563 0 4px, #E5E7EB 4px 6px, #4B5563 6px 8px, #E5E7EB 8px 10px)",
    "Restricted": "radial-gradient(#4B5563 1.2px, #E5E7EB 1.4px) 0 0 / 5px 5px",
}
# Leaflet dashArray: solid, dash-dot, dotted.
ACCESS_DASH = {"Walkable": "", "Conditional": "10 4 2 4", "Restricted": "1 5"}

EMPTY_NETWORK_TEXT = "No road segments match the selected filters."
WORKING_ASSUMPTION_NOTE = (
    "Missing access and foot tags are treated as Walkable as a working assumption, "
    "not as verified pedestrian accessibility."
)


def road_line_style(category: str, access: str) -> dict:
    """Colour by highway category, dash by pedestrian access. Roads never take pointer events."""
    return {
        "color": CATEGORY_COLORS[category],
        "weight": 3,
        "opacity": 0.9,
        "dashArray": ACCESS_DASH[access],
        "interactive": False,
    }


def _legend(values: Mapping[str, float], fills: Mapping[str, str], percentages: Mapping[str, float], order: tuple[str, ...]) -> ui.Tag:
    return ui.tags.div(
        *[
            ui.tags.div(
                ui.tags.span(class_="composition-swatch", style=f"background:{fills[name]}"),
                ui.tags.span(name, class_="composition-label"),
                ui.tags.span(f"{values[name]:.1f} km · {percentages[name]:.1f}%", class_="composition-value"),
                class_="composition-row",
            )
            for name in order if values.get(name, 0.0) > 0
        ],
        class_="composition-legend",
    )


def _stacked_bar(title: str, values: Mapping[str, float], fills: Mapping[str, str], total: float, order: tuple[str, ...]) -> ui.Tag:
    percentages = shares(values, total)
    segments = [
        ui.tags.span(class_="stack-segment", style=f"width:{percentages[name]:.2f}%;background:{fills[name]}", title=f"{name}: {percentages[name]:.1f}%")
        for name in order if percentages.get(name, 0.0) > 0
    ]
    return ui.tags.div(
        ui.h2(title),
        ui.tags.div(*segments, class_="stack-bar", role="img", aria_label=title),
        _legend(values, fills, percentages, order),
        class_="network-chart",
    )


def _donut(title: str, values: Mapping[str, float], fills: Mapping[str, str], total: float, order: tuple[str, ...]) -> ui.Tag:
    percentages = shares(values, total)
    stops, cursor = [], 0.0
    for name in order:
        share = percentages.get(name, 0.0)
        if share <= 0:
            continue
        stops.extend([f"{fills[name]} {cursor:.2f}%", f"{fills[name]} {min(cursor + share, 100):.2f}%"])
        cursor += share
    return ui.tags.div(
        ui.h2(title),
        ui.tags.div(
            ui.tags.div(ui.tags.div(class_="network-donut-hole"), class_="network-donut", style="background: conic-gradient(" + ", ".join(stops) + ");"),
            _legend(values, fills, percentages, order),
            class_="network-composition-chart",
        ),
        class_="network-chart",
    )


def network_bars(summary: NetworkSummary, empty_text: str = EMPTY_NETWORK_TEXT) -> ui.Tag:
    """Results layout: two compact stacked bars drawn from one summary (one shared total)."""
    if summary.total_km <= 0:
        return ui.tags.p(empty_text, class_="muted network-empty")
    return ui.tags.div(
        _stacked_bar("Network accessibility", summary.by_access, ACCESS_FILLS, summary.total_km, ACCESS_CLASSES),
        _stacked_bar("Network composition", summary.by_category, CATEGORY_COLORS, summary.total_km, HIGHWAY_CATEGORIES),
        class_="network-bars",
    )


def network_donuts(summary: NetworkSummary, empty_text: str = EMPTY_NETWORK_TEXT) -> ui.Tag:
    """Details layout: composition donut with the accessibility stacked bar below it, from one summary."""
    if summary.total_km <= 0:
        return ui.tags.p(empty_text, class_="muted network-empty")
    return ui.tags.div(
        _donut("Network composition", summary.by_category, CATEGORY_COLORS, summary.total_km, HIGHWAY_CATEGORIES),
        _stacked_bar("Network accessibility", summary.by_access, ACCESS_FILLS, summary.total_km, ACCESS_CLASSES),
        class_="network-donuts",
    )

