.environment-value.unavailable { color: var(--muted); font-size: 12px; }
.network-composition-chart { display: grid; grid-template-columns: 132px 1fr; align-items: center; gap: 18px; margin-top: 8px; }
.network-donut { width: 132px; height: 132px; border-radius: 50%; position: relative; }
.network-donut-hole { position: absolute; inset: 30px; border-radius: 50%; background: var(--paper); }
.composition-legend { display: grid; gap: 4px; }
.composition-row { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; align-items: center; gap: 7px; min-height: 23px; font-size: 12px; }
.composition-swatch { width: 10px; height: 10px; border-radius: 3px; }
.composition-label { overflow-wrap: anywhere; }
.composition-value { font-weight: 700; }
.muted { color: var(--muted); font-size: 12px; }

.status-bar {
  position: absolute; bottom: 16px; left: 16px; z-index: 850;
  max-width: calc(100% - 32px); border-radius: 8px; padding: 6px 10px;
  background: #245B45; color: #fff; box-shadow: 0 2px 8px rgba(28,43,35,.28);
  font-size: 12.5px; font-weight: 500; line-height: 1.3; pointer-events: none;
}
.status-chip-content { display: flex; align-items: center; gap: 6px; min-width: 0; }
.status-chip-icon { flex: none; }
.status-chip-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.demo-notice { position: absolute; right: 16px; bottom: 16px; z-index: 850; border-radius: 4px; padding: 7px 10px; background: rgba(255,255,255,.92); color: var(--muted); font-size: 11px; }
.sliding-panel.open ~ .demo-notice { display: none; }
.board-tooltip {
  position: fixed; z-index: 900; display: none; pointer-events: none;
  padding: 6px 10px; border-radius: 8px; background: #fff; color: #1C2B23;
  box-shadow: 0 2px 8px rgba(28,43,35,.25); font-size: 12px; line-height: 1.35;
}
.board-tooltip strong { display: block; font-size: 13px; color: #245B45; }
.board-tooltip span { color: var(--muted); }

@media (max-width: 900px) {
  .sliding-panel { width: min(420px, 100%); flex-basis: min(420px, 100%); }
  .results-toggle { right: auto; }
}
@media (max-width: 640px) {
  .app-header { height: 56px; }
  .app-shell { top: 56px; }
  .sliding-panel { height: calc(100% - 56px); margin-top: 56px; }
  .app-title { font-size: 18px; }
  .filter-panel { top: 8px; left: 8px; width: calc(100% - 16px); }
  .filter-panel:not(.collapsed) { max-height: calc(100vh - 72px); }
  .layers-control { top: 8px; right: 8px; }
  .board-mode-button { top: 8px; right: 58px; height: 42px; padding: 0 10px; font-size: 12px; }
  .status-bar { left: 8px; bottom: 8px; max-width: calc(100% - 16px); font-size: 12px; padding: 5px 8px; }
  .demo-notice { display: none; }
  .sliding-panel { width: 100%; }
}

/* Filter choice chips */
#walking_speed, #walk_time {
  margin-bottom: 0;
}
#walking_speed .shiny-options-group,
#walk_time .shiny-options-group {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}
#walk_time .shiny-options-group {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
#walking_speed .radio,
#walk_time .radio {
  min-width: 0;
  margin: 0;
}
#walking_speed .radio label,
#walk_time .radio label {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 0;
  border: 1.5px solid #C5D0C8;
  border-radius: 9px;
  background: #EEF3EE;
  color: var(--ink);
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}
#walking_speed .radio label:hover,
#walk_time .radio label:hover {
  background: var(--light-green);
}
#walking_speed .radio label input,
#walk_time .radio label input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
#walking_speed .radio label:has(input:checked),
#walk_time .radio label:has(input:checked) {
  border-color: #123A2B;
  background: var(--primary-green);
  color: #fff;
  box-shadow: 0 0 0 2px rgba(36,91,69,.25);
}
#walking_speed .radio label:has(input:checked)::after,
#walk_time .radio label:has(input:checked)::after {
  content: "\2713";
  position: absolute;
  top: 4px;
  right: 7px;
  font-size: 12px;
  line-height: 1;
}
.chip-value-custom { font-size: 13px !important; }
.filter-chip-content { display: flex; flex-direction: column; align-items: center; line-height: 1; }
.filter-chip-content .chip-value { font-size: 18px; }
.filter-chip-content .chip-unit { margin-top: 5px; font-size: 11px; font-weight: 500; opacity: .75; }
.custom-speed, .custom-time { display: none; }
.custom-speed.visible, .custom-time.visible { display: block; }
.custom-speed .shiny-input-container, .custom-time .shiny-input-container { margin-bottom: 12px; }
.filter-content select,
.filter-content input[type='number'] {
  width: 100%; min-height: 48px; border: 0; border-radius: 9px; background: #F3F6F3;
  padding: 0 14px; color: var(--ink); font-size: 15px;
}
.filter-content select { appearance: auto; }
.park-search { position: relative; }
.park-search .park-search-icon { position: absolute; left: 11px; top: 11px; z-index: 5; color: #6B7A71; pointer-events: none; }
.park-search .selectize-input { min-height: 38px; padding: 8px 30px 8px 34px; border-radius: 5px; box-shadow: none; }
.park-search .selectize-dropdown { border-radius: 5px; z-index: 1000; }
.park-search .selectize-control.plugin-clear_button .clear { color: #6B7A71; }
.filter-actions { grid-template-columns: 1fr; gap: 8px; }
.filter-actions .primary-action { width: 100%; }
.filter-actions .secondary-action {
  border: 0; background: transparent; color: #718078; font-weight: 600; text-transform: none;
}



/* Professional nature palette refinements */
.app-header { height: 64px; padding: 0 24px; }
.app-shell { top: 64px; }
.app-title { font-size: 22px; letter-spacing: -0.01em; }
.filter-panel { border: 1px solid rgba(232, 237, 232, 0.9); border-radius: 10px; }
.filter-toggle { height: 52px; }
.filter-content { padding: 12px 16px 16px; }
.filter-content label { color: var(--ink); }
.primary-action, .secondary-action { min-height: 44px; border-radius: 8px; }
.sliding-panel { background: #F5F7F4; }
/* .app-shell already starts below the header, so the shared panel's extra top margin only adds dead space above Details. */
.sliding-panel:has(.details-content) { margin-top: 0; height: 100%; }
.details-content { padding-top: 20px; }
.search-summary { gap: 10px; }
.summary-item { border: 0; border-radius: 10px; }
.park-result { border-radius: 9px; }
.layers-content, .layers-button { border-radius: 9px; }
.leaflet-control-attribution { font-size: 10px; }

/* Road Filter tab, road layer pane, and walking-network charts */
.leaflet-road_network-pane { pointer-events: none; }
.filter-content .nav-tabs { margin-bottom: 10px; border-bottom: 1px solid var(--line); gap: 2px; }
.filter-content .nav-tabs .nav-link { font-size: 13px; font-weight: 600; padding: 6px 12px; color: var(--muted); border-radius: 6px 6px 0 0; }
.filter-content .nav-tabs .nav-link:hover { color: var(--green); border-color: transparent; }
.filter-content .nav-tabs .nav-link.active { color: #fff; background: var(--green); border-color: var(--green); }
.filter-content .tab-content > .tab-pane { padding: 0; }
.road-check-groups .shiny-input-container { width: 100%; margin: 0 0 8px; }
.road-check-groups .control-label { display: block; margin: 0 0 3px; font-size: 13px; font-weight: 700; color: var(--ink); }
.road-check-groups .shiny-options-group { display: grid; gap: 0; padding: 4px 8px; border: 1px solid var(--line); border-radius: 7px; background: rgba(255, 255, 255, .6); }
.road-check-groups .checkbox, .road-check-groups .form-check { margin: 0; min-height: 0; padding-left: 0; }
.road-check-groups label { display: flex; align-items: center; gap: 8px; margin: 0; padding: 2px 0; font-size: 13px; font-weight: 400; cursor: pointer; }
.road-check-groups input[type="checkbox"] { margin: 0; flex: none; width: 15px; height: 15px; accent-color: var(--green); }
.filter-content, .details-content { --bs-primary: #245B45; --bs-primary-rgb: 36, 91, 69; }
.road-check-groups input[type="checkbox"]:checked { background-color: var(--green); border-color: var(--green); }
.filter-content .form-check-input:checked, .details-content .form-check-input:checked { background-color: var(--green); border-color: var(--green); }
.filter-content .form-check-input:focus, .details-content .form-check-input:focus { border-color: var(--green); box-shadow: 0 0 0 .15rem rgba(36, 91, 69, .25); }
.network-donuts h2, .network-bars h2 { font-size: 14px; margin: 12px 0 4px; }
.network-chart { margin: 0 0 6px; }
.network-empty { font-size: 13px; }
.stack-bar { display: flex; height: 14px; border-radius: 7px; overflow: hidden; background: #E5E7EB; border: 1px solid var(--line); }
.stack-segment { display: block; height: 100%; }
.network-bars .composition-legend { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 2px 12px; margin-top: 6px; }
.network-chart .composition-label { overflow-wrap: normal; }
.network-donuts .stack-bar + .composition-legend { margin-top: 6px; }
.results-network { margin: 0 0 14px; }
.details-explore { margin: 14px 0 4px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255, 255, 255, .6); }
.details-explore-summary { display: flex; align-items: center; justify-content: space-between; padding: 8px 10px; font-size: 14px; font-weight: 700; cursor: pointer; list-style: none; }
.details-explore-summary::-webkit-details-marker { display: none; }
.details-explore-summary::after { content: "⌄"; color: var(--green); transition: transform .15s; }
.details-explore[open] > .details-explore-summary::after { transform: rotate(180deg); }
.details-explore .road-check-groups { padding: 0 10px 4px; }
